ruleSearch.bookList:
@js:(function(){
var out=[];
var k='';
try{
var bu=String(baseUrl);
var i=bu.indexOf('hgk=');
if(i>=0){ k=bu.substring(i+4); var q=k.indexOf('&'); if(q>=0)k=k.substring(0,q); k=decodeURIComponent(k); }
if(!k){ var j=bu.indexOf('/search/'); if(j>=0){ k=bu.substring(j+8); var q2=k.indexOf('?'); if(q2>=0)k=k.substring(0,q2); k=decodeURIComponent(k); } }
}catch(e0){}
if(!k)return out;
try{
var h=String(java.ajax(HG_BASE+'/search/'+java.encodeURI(k)));
var l1=HG_SRCH(h);
for(var i=0;i<l1.length;i++)out.push(l1[i]);
}catch(e){}
try{
var t=String(java.ajax(HG_BASE+'/incent_resource/suggestion?app_id=8662&web_id=hgweb&count=20&query='+java.encodeURI(k)));
var d=JSON.parse(t);
var sl=d.suggest_list||[];
for(var j=0;j<sl.length;j++){
var it=sl[j];
var sid=String(it.keyword||'');
if(!sid||sid.length<10)continue;
var vd=it.video_data||{};
if(!vd.series_id)continue;
var nm=String(it.name||vd.series_title||'');
if(!nm)continue;
var kn=[];
var cl=vd.category_list||[];
for(var x=0;x<cl.length;x++)kn.push(String(cl[x].name||''));
var ex=String(vd.episode_right_text||'');
var hs=vd.hot_score_data||{};
if(hs.text)ex=ex+' · '+String(hs.text);
out.push(HG_ITEM(sid,nm,String(vd.series_cover||''),kn.join(','),ex,''));
}
}catch(e2){}
var seen={},res=[];
for(var m=0;m<out.length;m++){
try{ var o=JSON.parse(out[m]); if(!o.url||seen[o.url])continue; seen[o.url]=1; res.push(out[m]); }catch(e3){}
}
return res;
})()

